/* Marked-gadget SEAM transfer matrices for all tournaments of order n (iso classes generated by vertex
   extension of order n-1 classes), all ports (u,z). Output distinct matrices (sorted later). */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef long long ll; typedef unsigned long long ull;
#define MAXN 9
static int nperm; static unsigned char perms[40320][MAXN];
static void genperms(int n){ int idx[MAXN]; for(int i=0;i<n;i++) idx[i]=i; nperm=0;
  while(1){ for(int i=0;i<n;i++) perms[nperm][i]=idx[i]; nperm++;
    int i=n-2; while(i>=0 && idx[i]>idx[i+1]) i--; if(i<0) break;
    int j=n-1; while(idx[j]<idx[i]) j--; int t=idx[i]; idx[i]=idx[j]; idx[j]=t;
    for(int l=i+1,r=n-1;l<r;l++,r--){t=idx[l];idx[l]=idx[r];idx[r]=t;} } }
/* encode tournament on n vertices: bit for pair (i<j) = 1 iff i->j */
static ull enc(int n,int g[MAXN][MAXN]){ ull m=0; int b=0; for(int i=0;i<n;i++) for(int j=i+1;j<n;j++){ if(g[i][j]) m|=1ULL<<b; b++; } return m; }
static void dec(int n,ull m,int g[MAXN][MAXN]){ int b=0; for(int i=0;i<n;i++){ g[i][i]=0; for(int j=i+1;j<n;j++){ int e=(m>>b)&1; b++; g[i][j]=e; g[j][i]=1-e; } } }
static ull canon(int n,int g[MAXN][MAXN]){ ull best=~0ULL; int sc[MAXN]; for(int i=0;i<n;i++){sc[i]=0; for(int j=0;j<n;j++) sc[i]+=g[i][j];}
  for(int q=0;q<nperm;q++){ unsigned char*p=perms[q]; /* p[new]=old ; require nonincreasing score order for pruning */
    int ok=1; for(int i=0;i+1<n;i++) if(sc[p[i]]<sc[p[i+1]]){ok=0;break;} if(!ok) continue;
    ull m=0; int b=0; for(int i=0;i<n;i++) for(int j=i+1;j<n;j++){ if(g[p[i]][p[j]]) m|=1ULL<<b; b++; } if(m<best) best=m; }
  return best; }
/* hash set of ull */
static ull *hs; static size_t hcap; static size_t hcnt;
static int hins(ull k){ k+=1; size_t i=(k*0x9E3779B97F4A7C15ULL)>>20 & (hcap-1); while(hs[i]){ if(hs[i]==k) return 0; i=(i+1)&(hcap-1);} hs[i]=k; hcnt++; return 1; }
static int adj[16][16]; static ll dp[1<<12][12], dps[1<<12][12], Hs[1<<12];
static void resp(int n,int port,ll out[3]){ int full=(1<<n)-1;
  for(int m=0;m<=full;m++) for(int v=0;v<n;v++){dp[m][v]=0;dps[m][v]=0;}
  for(int v=0;v<n;v++){dp[1<<v][v]=1;dps[1<<v][v]=1;}
  for(int m=1;m<=full;m++) for(int v=0;v<n;v++){ ll a=dp[m][v], c=dps[m][v]; if(!a && !c) continue;
    for(int w=0;w<n;w++) if(!(m>>w&1)){ if(a&&adj[v][w]) dp[m|1<<w][w]+=a; if(c&&adj[w][v]) dps[m|1<<w][w]+=c; } }
  Hs[0]=1; for(int m=1;m<=full;m++){ll s=0; for(int v=0;v<n;v++) s+=dp[m][v]; Hs[m]=s;}
  ll R=0; for(int m=1;m<=full;m++) if(m>>port&1) R+=dp[m][port]*Hs[full^m];
  out[0]=Hs[full]; out[1]=dps[full][port]; out[2]=R; }
static int pre_n[3]={1,2,3};
static void build(int p,int gn,int g[MAXN][MAXN],int u,int z,int*nn,int*port){ int pn=pre_n[p]; int n=pn+gn; *nn=n;
  for(int i=0;i<n;i++) for(int j=0;j<n;j++) adj[i][j]=0; int a=pn-1;
  if(p==1) adj[0][1]=1; if(p==2){adj[0][1]=1;adj[1][2]=1;adj[2][0]=1;}
  for(int i=0;i<gn;i++) for(int j=0;j<gn;j++) adj[pn+i][pn+j]=g[i][j];
  for(int i=0;i<gn;i++) for(int j=0;j<pn;j++){adj[pn+i][j]=1; adj[j][pn+i]=0;}
  adj[pn+u][a]=0; adj[a][pn+u]=1; *port=pn+z; }
int main(int argc,char**argv){ int N=atoi(argv[1]);
  /* classes: start with order 1 */
  ull *cur=malloc(sizeof(ull)*1); int ncur=1; cur[0]=0;
  for(int n=2;n<=N;n++){ genperms(n); hcap=1<<22; hs=calloc(hcap,sizeof(ull)); hcnt=0;
    ull *nxt=malloc(sizeof(ull)*200000); int nn=0;
    for(int c=0;c<ncur;c++){ int g[MAXN][MAXN]; dec(n-1,cur[c],g);
      for(int pat=0;pat<(1<<(n-1));pat++){ for(int i=0;i<n-1;i++){ g[i][n-1]=(pat>>i)&1; g[n-1][i]=1-g[i][n-1]; } g[n-1][n-1]=0;
        ull cf=canon(n,g); if(hins(cf)) nxt[nn++]=cf; } }
    free(hs); free(cur); cur=nxt; ncur=nn; fprintf(stderr,"order %d: %d classes\n",n,ncur); }
  ll P[3][3]={{1,1,1},{1,0,2},{3,1,3}}; ll A[3][3]; for(int i=0;i<3;i++) for(int j=0;j<3;j++) A[i][j]=P[j][i];
  ll det=A[0][0]*(A[1][1]*A[2][2]-A[1][2]*A[2][1])-A[0][1]*(A[1][0]*A[2][2]-A[1][2]*A[2][0])+A[0][2]*(A[1][0]*A[2][1]-A[1][1]*A[2][0]);
  ll adjm[3][3]; for(int i=0;i<3;i++) for(int j=0;j<3;j++){int r1=(j+1)%3,r2=(j+2)%3,c1=(i+1)%3,c2=(i+2)%3; adjm[i][j]=A[r1][c1]*A[r2][c2]-A[r1][c2]*A[r2][c1];}
  for(int c=0;c<ncur;c++){ int g[MAXN][MAXN]; dec(N,cur[c],g);
    for(int u=0;u<N;u++) for(int z=0;z<N;z++){ ll Y[3][3];
      for(int p=0;p<3;p++){int n,port; build(p,N,g,u,z,&n,&port); ll o[3]; resp(n,port,o); for(int i=0;i<3;i++) Y[i][p]=o[i];}
      ll M[9]; for(int i=0;i<3;i++) for(int j=0;j<3;j++){ ll s=0; for(int k=0;k<3;k++) s+=Y[i][k]*adjm[k][j]; if(s%det){fprintf(stderr,"nonint\n");return 1;} M[3*i+j]=s/det; }
      printf("%lld %lld %lld %lld %lld %lld %lld %lld %lld\n",M[0],M[1],M[2],M[3],M[4],M[5],M[6],M[7],M[8]); } }
  return 0; }
